<body>
<div class="wrap">
  <h1>Hitelszámoló</h1>
  <p class="hint">Add meg a hitelösszeget, az éves kamatot és a futamidőt, majd számold ki a havi törlesztőt és a tőke–kamat bontást.</p>

  <form id="form" class="card" novalidate>
    <div class="field">
      <label for="amount">Hitelösszeg (forint)</label>
      <input id="amount" type="number" inputmode="decimal" min="0" step="any" placeholder="pl. 3 000 000">
    </div>
    <div class="field">
      <label for="rate">Éves kamat (%)</label>
      <input id="rate" type="number" inputmode="decimal" min="0" step="any" placeholder="pl. 5,5">
    </div>
    <div class="field">
      <label for="months">Futamidő (hónap)</label>
      <input id="months" type="number" inputmode="numeric" min="1" step="1" placeholder="pl. 240">
    </div>
    <div class="btn-row">
      <button type="submit" class="primary">Kiszámolom</button>
      <button type="button" id="clear">Törlés</button>
    </div>
    <p class="error" id="error" role="alert"></p>
  </form>

  <div id="results"></div>
</div>

<script>
  (function () {
    var KEY = 'hitel-inputs';
    var amountEl = document.getElementById('amount');
    var rateEl = document.getElementById('rate');
    var monthsEl = document.getElementById('months');
    var form = document.getElementById('form');
    var errorEl = document.getElementById('error');
    var results = document.getElementById('results');
    var clearBtn = document.getElementById('clear');

    function nf(value) {
      return Math.round(value).toLocaleString('hu-HU');
    }
    function num(el) {
      var raw = el.value.replace(',', '.').trim();
      return raw === '' ? NaN : Number(raw);
    }
    function persist() {
      var state = { amount: amountEl.value, rate: rateEl.value, months: monthsEl.value };
      try {
        if (window.alfy && window.alfy.storage) {
          window.alfy.storage.set(KEY, state);
        }
      } catch (e) { /* storage unavailable */ }
    }
    function restore() {
      if (!window.alfy || !window.alfy.storage) return;
      try {
        var s = window.alfy.storage.get(KEY);
        if (s) {
          amountEl.value = s.amount || '';
          rateEl.value = s.rate || '';
          monthsEl.value = s.months || '';
        }
      } catch (e) { /* storage unavailable */ }
    }

    function emptyState() {
      results.innerHTML =
        '<div class="empty">Még nincs számítás. Add meg a fenti adatokat, majd nyomd meg a „Kiszámolom” gombot.</div>';
    }

    function render(data) {
      var rows = '';
      for (var i = 0; i < data.years.length; i++) {
        var y = data.years[i];
        rows += '<tr><td>' + y.year + '.</td><td>' + nf(y.capital) + '</td><td class="interest">' + nf(y.interest) + '</td><td>' + nf(y.total) + '</td><td>' + nf(y.balance) + '</td></tr>';
      }
      results.innerHTML =
        '<div class="summary">' +
          '<div class="stat accent"><div class="label">Havi törlesztő</div><div class="value">' + nf(data.payment) + ' Ft</div></div>' +
          '<div class="stat"><div class="label">Teljes fizetendő</div><div class="value">' + nf(data.totalPaid) + ' Ft</div></div>' +
          '<div class="stat"><div class="label">Teljes kamat</div><div class="value">' + nf(data.totalInterest) + ' Ft</div></div>' +
        '</div>' +
        '<div class="card"><h2>Éves bontás</h2><div class="table-wrap"><table>' +
          '<thead><tr><th>Év</th><th>Tőke</th><th>Kamat</th><th>Összesen</th><th>Fennálló</th></tr></thead>' +
          '<tbody>' + rows + '</tbody>' +
        '</table></div></div>';
    }

    function compute() {
      var principal = num(amountEl);
      var annual = num(rateEl);
      var n = num(monthsEl);

      if (isNaN(principal) || principal <= 0) {
        errorEl.textContent = 'Add meg a pozitív hitelösszeget forintban.';
        return false;
      }
      if (isNaN(annual) || annual < 0) {
        errorEl.textContent = 'Add meg az éves kamatot százalékban (0 vagy nagyobb).';
        return false;
      }
      if (isNaN(n) || n < 1 || Math.floor(n) !== n) {
        errorEl.textContent = 'Add meg a futamidőt egész hónapban (legalább 1).';
        return false;
      }

      var i = annual / 100 / 12;
      var payment;
      if (i === 0) {
        payment = principal / n;
      } else {
        payment = principal * i / (1 - Math.pow(1 + i, -n));
      }

      var balance = principal;
      var totalInterest = 0;
      var years = [];
      var yearIndex = 1;
      var yc = 0, yi = 0, yt = 0;

      for (var m = 1; m <= n; m++) {
        var interest = balance * i;
        var capital = payment - interest;
        balance -= capital;
        if (balance < 0) balance = 0;
        totalInterest += interest;
        yc += capital;
        yi += interest;
        yt += payment;
        if (m % 12 === 0 || m === n) {
          years.push({ year: yearIndex, capital: yc, interest: yi, total: yt, balance: balance });
          yearIndex++;
          yc = 0; yi = 0; yt = 0;
        }
      }

      errorEl.textContent = '';
      render({
        payment: payment,
        totalPaid: payment * n,
        totalInterest: totalInterest,
        years: years
      });
      return true;
    }

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      persist();
      compute();
    });
    form.addEventListener('input', persist);

    clearBtn.addEventListener('click', function () {
      amountEl.value = '';
      rateEl.value = '';
      monthsEl.value = '';
      errorEl.textContent = '';
      persist();
      emptyState();
    });

    restore();
    if (amountEl.value || rateEl.value || monthsEl.value) {
      compute();
    } else {
      emptyState();
    }
  })();
</script>
</body>
